package kan23_test

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/aarush323/heimdall-fixture-pay/internal/app"
)

func TestCreatePaymentResponseUsesDocumentedMerchantIDField(t *testing.T) {
	mfFixedNow := time.Date(2026, 11, 8, 10, 0, 0, 0, time.UTC)
	h := app.New(app.Config{Now: func() time.Time { return mfFixedNow }})

	req := httptest.NewRequest(http.MethodPost, "/payments", strings.NewReader(`{"amount": 1000, "currency": "USD"}`))
	req.Header.Set("X-Merchant-ID", "m-1")
	req.Header.Set("Content-Type", "application/json")
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusCreated {
		t.Fatalf("status %d, want 201; body %s", rec.Code, rec.Body)
	}

	var body map[string]json.RawMessage
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatal(err)
	}
	raw, ok := body["merchant_id"]
	if !ok {
		t.Fatalf("response has no merchant_id field as api/openapi.yaml documents: body %s", rec.Body)
	}
	var got string
	if err := json.Unmarshal(raw, &got); err != nil {
		t.Fatal(err)
	}
	if got != "m-1" {
		t.Errorf("merchant_id = %q, want m-1", got)
	}
}

package kan23_test

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"

	"github.com/aarush323/heimdall-fixture-pay/internal/app"
)

func TestRefundResponseCarriesRefundRef(t *testing.T) {
	h := app.New(app.Config{Now: func() time.Time { return time.Date(2026, 11, 8, 10, 0, 0, 0, time.UTC) }})

	payReq := httptest.NewRequest(http.MethodPost, "/payments", strings.NewReader(`{"amount": 1000, "currency": "USD"}`))
	payReq.Header.Set("X-Merchant-ID", "m-1")
	payReq.Header.Set("Content-Type", "application/json")
	payRec := httptest.NewRecorder()
	h.ServeHTTP(payRec, payReq)
	if payRec.Code != http.StatusCreated {
		t.Fatalf("create payment: status %d, want 201; body %s", payRec.Code, payRec.Body)
	}
	var created struct {
		ID string `json:"id"`
	}
	if err := json.Unmarshal(payRec.Body.Bytes(), &created); err != nil {
		t.Fatalf("payment response is not JSON: %v", err)
	}

	refReq := httptest.NewRequest(http.MethodPost, "/payments/"+created.ID+"/refunds", strings.NewReader(`{"amount": 300}`))
	refReq.Header.Set("X-Merchant-ID", "m-1")
	refReq.Header.Set("Content-Type", "application/json")
	refRec := httptest.NewRecorder()
	h.ServeHTTP(refRec, refReq)
	if refRec.Code != http.StatusCreated {
		t.Fatalf("refund: status %d, want 201; body %s", refRec.Code, refRec.Body)
	}

	var body struct {
		RefundRef string `json:"refund_ref"`
	}
	if err := json.Unmarshal(refRec.Body.Bytes(), &body); err != nil {
		t.Fatalf("refund response is not JSON: %v", err)
	}
	if body.RefundRef == "" {
		t.Errorf("refund response has no refund_ref field; the ledger keys postings by it: %s", refRec.Body)
	}
}

