package idempotency_test

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/aarush323/heimdall-fixture-pay/internal/app"
)

func doRefund(t *testing.T, h http.Handler, paymentID, key string) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(http.MethodPost, "/payments/"+paymentID+"/refunds", strings.NewReader(`{"amount": 300}`))
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("X-Merchant-ID", "m-1")
	if key != "" {
		req.Header.Set("Idempotency-Key", key)
	}
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

func TestRepeatRefundWithSameIdempotencyKeyReturnsOriginal(t *testing.T) {
	h := app.New(app.Config{})
	req := httptest.NewRequest(http.MethodPost, "/payments", strings.NewReader(`{"amount": 1000, "currency": "USD"}`))
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("X-Merchant-ID", "m-1")
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusCreated {
		t.Fatalf("create payment: status %d, want 201; body %s", rec.Code, rec.Body)
	}
	var payment struct {
		ID string `json:"id"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &payment); err != nil {
		t.Fatal(err)
	}

	first := doRefund(t, h, payment.ID, "k-1")
	if first.Code != http.StatusCreated {
		t.Fatalf("first refund: status %d, want 201; body %s", first.Code, first.Body)
	}
	var firstRefund struct {
		ID string `json:"id"`
	}
	if err := json.Unmarshal(first.Body.Bytes(), &firstRefund); err != nil {
		t.Fatal(err)
	}

	second := doRefund(t, h, payment.ID, "k-1")
	if second.Code != http.StatusOK {
		t.Fatalf("repeat refund with the same Idempotency-Key: status %d, want 200; body %s", second.Code, second.Body)
	}
	var secondRefund struct {
		ID string `json:"id"`
	}
	if err := json.Unmarshal(second.Body.Bytes(), &secondRefund); err != nil {
		t.Fatal(err)
	}
	if secondRefund.ID != firstRefund.ID {
		t.Errorf("repeat refund id = %q, want the original %q", secondRefund.ID, firstRefund.ID)
	}
}
